import { createHash } from "node:crypto";
import manifest from "@/lib/sat/cfdi40/manifest.json";
import { Cfdi40Error, cfdi40Issue, type Cfdi40IssueCode } from "./errors";

// Fase 5C.7: the official CFDI 4.0 XSD set (cfdv40.xsd and the schemas it imports), from
// src/lib/sat/cfdi40/cfdv40-xsd.json, generated byte-exact from resources/sat/cfdi40 by
// scripts/sat/cfdi40-xsd-bundle.mjs. A JSON module, bundled with the server code: no runtime
// file read and no download. Before use, every text is re-hashed against the manifest, the
// set must be exactly the manifest's XSD entries, each schema must declare the expected
// targetNamespace, and its xs:import/include/redefine/override must be exactly the declared,
// versioned dependencies. Anything else fails closed.

export type Cfdi40XsdSchema = {
  readonly url: string;
  readonly name: string;
  readonly namespace: string;
  readonly imports: readonly string[];
  readonly sha256: string;
  /** Exact UTF-8 bytes of the official file. */
  readonly bytes: Uint8Array;
};
export type Cfdi40XsdBundle = {
  /** Official URL of cfdv40.xsd (its base URI). */
  readonly rootUrl: string;
  /** SHA-256 over the sorted "url sha256" lines of the set: the XSD version in use. */
  readonly bundleSha256: string;
  /** Allowlist: official URL → schema. */
  readonly schemas: ReadonlyMap<string, Cfdi40XsdSchema>;
};
export type Cfdi40XsdBundleSource = {
  root: string;
  resources: readonly {
    url: string;
    name: string;
    namespace: string;
    imports: readonly string[];
    sha256: string;
    text: string;
  }[];
};
type ManifestResource = {
  name: string;
  kind: string;
  url: string;
  sha256: string;
  namespace?: string;
  imports?: readonly string[];
};

const integrity = (code: Cfdi40IssueCode, name: string) =>
  new Cfdi40Error([cfdi40Issue(code, "XSD/" + name, "ORBIT")]);
const sha256 = (data: Uint8Array) =>
  createHash("sha256").update(data).digest("hex");
const references = (text: string) =>
  [
    ...text.matchAll(
      /<xs:(?:import|include|redefine|override)\b[^>]*?\bschemaLocation="([^"]+)"/g,
    ),
  ].map((m) => m[1]);
const targetNamespace = (text: string) =>
  /<xs:schema\b[^>]*?\btargetNamespace="([^"]+)"/.exec(text)?.[1] ?? null;
const sameList = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((value, i) => value === b[i]);

export const cfdi40XsdRootUrl =
  "http://www.sat.gob.mx/sitio_internet/cfd/4/cfdv40.xsd";

/**
 * Checks a bundle against the manifest. Throws CFDI_XSD_SCHEMA_UNAVAILABLE (a manifest
 * schema missing) or CFDI_XSD_SCHEMA_INTEGRITY_FAILED (modified text, wrong hash, extra
 * schema, unexpected namespace, or an import/include not declared in the manifest).
 */
export function verifyCfdi40XsdBundle(
  source: Cfdi40XsdBundleSource,
  resources: readonly ManifestResource[] = manifest.resources as ManifestResource[],
): Cfdi40XsdBundle {
  const expected = resources.filter((r) => r.kind === "XSD");
  if (
    source.root !== cfdi40XsdRootUrl ||
    !expected.some((r) => r.url === cfdi40XsdRootUrl)
  )
    throw integrity("CFDI_XSD_SCHEMA_UNAVAILABLE", "cfdv40.xsd");
  for (const entry of source.resources)
    if (!expected.some((e) => e.url === entry.url))
      throw integrity("CFDI_XSD_SCHEMA_INTEGRITY_FAILED", entry.name);
  const schemas = new Map<string, Cfdi40XsdSchema>();
  for (const entry of expected) {
    const found = source.resources.find((r) => r.url === entry.url);
    if (!found) throw integrity("CFDI_XSD_SCHEMA_UNAVAILABLE", entry.name);
    const bytes = new Uint8Array(Buffer.from(found.text, "utf8"));
    const imports = references(found.text);
    if (
      found.sha256 !== entry.sha256 ||
      sha256(bytes) !== entry.sha256 ||
      !entry.namespace ||
      found.namespace !== entry.namespace ||
      targetNamespace(found.text) !== entry.namespace ||
      !sameList(imports, entry.imports ?? []) ||
      !sameList(found.imports, imports)
    )
      throw integrity("CFDI_XSD_SCHEMA_INTEGRITY_FAILED", entry.name);
    schemas.set(
      entry.url,
      Object.freeze({
        url: entry.url,
        name: entry.name,
        namespace: entry.namespace,
        imports: Object.freeze([...imports]),
        sha256: entry.sha256,
        bytes,
      }),
    );
  }
  // Closed graph: every reference is a versioned schema of this set.
  for (const schema of schemas.values())
    for (const url of schema.imports)
      if (!schemas.has(url))
        throw integrity("CFDI_XSD_SCHEMA_INTEGRITY_FAILED", schema.name);
  const lines = [...schemas.values()]
    .map((s) => `${s.url} ${s.sha256}`)
    .sort()
    .join("\n");
  return Object.freeze({
    rootUrl: cfdi40XsdRootUrl,
    bundleSha256: sha256(Buffer.from(lines, "utf8")),
    schemas,
  });
}

let loaded: Promise<Cfdi40XsdBundle> | undefined;
/** The verified official XSD bundle, loaded once (lazily, like the large catalogs). */
export function loadCfdi40XsdBundle() {
  return (loaded ??= import("@/lib/sat/cfdi40/cfdv40-xsd.json").then((module) =>
    verifyCfdi40XsdBundle(module.default),
  ));
}

/**
 * The bytes a schema import may load: only an absolute official SAT URL allowlisted by the
 * bundle, exactly as written. http(s) elsewhere, file:, data:, UNC or Windows paths, relative
 * or ".." paths, localhost, private or metadata addresses, queries and fragments are never
 * in the allowlist, so nothing is read from disk or the network. Returns null when refused.
 */
export function resolveSatXsdImport(
  bundle: Cfdi40XsdBundle,
  location: string,
): Uint8Array | null {
  return isOfficialSatXsdLocation(location)
    ? (bundle.schemas.get(location)?.bytes ?? null)
    : null;
}

/** An absolute official SAT URL exactly as written (shared with the stamped XSD set). */
export function isOfficialSatXsdLocation(location: string) {
  let url: URL | null = null;
  try {
    url = new URL(location);
  } catch {
    url = null;
  }
  return (
    url !== null &&
    url.href === location &&
    url.protocol === "http:" &&
    url.host === "www.sat.gob.mx" &&
    !url.search &&
    !url.hash &&
    !location.split("/").includes("..")
  );
}
